// RequireFields returns ErrInvalidArgument naming the first of fields (m's
// top-level field names) m leaves unset: a message without a value, a
// repeated or map field without elements. The REQUIRED document columns are
// NOT NULL, so a write without one would otherwise fail in the database.
func RequireFields(m proto.Message, fields ...string) error {
	r := m.ProtoReflect()
	for _, f := range fields {
		fd := r.Descriptor().Fields().ByName(protoreflect.Name(f))
		if fd == nil {
			continue
		}
		set := r.Has(fd)
		if fd.IsList() {
			set = r.Get(fd).List().Len() > 0
		} else if fd.IsMap() {
			set = r.Get(fd).Map().Len() > 0
		}
		if !set {
			return fmt.Errorf("%w: %s is required", ErrInvalidArgument, f)
		}
	}
	return nil
}

// AllWild reports whether every id of a split parent name is AIP-159's "-":
// a read across every parent. A parent with some ids named and some "-"
// ("venues/v1/events/-") reads under the named ones only.
func AllWild(ids []string) bool {
	for _, id := range ids {
		if id != "-" {
			return false
		}
	}
	return true
}

// Joined holds what join tables keep for a page of rows: the names each
// row's field lists, by field and then by the row's key.
type Joined map[string]map[string][]string

// Join is a join table keeping a repeated reference field: one row per
// element, in the order the field lists them (rows are keyed by ULIDs minted
// in that order).
type Join struct {
	// Field is the proto field it keeps, for errors.
	Field string
	// Table is the quoted, schema-qualified join table; Key its key column.
	Table, Key string
	// Owner is its column holding the owner's key, Target the one holding
	// the target's key, and Name the one holding the target's full resource
	// name ("" when the name is rebuilt from the key, see Collection).
	Owner, Target, Name string
	// TargetTable is the quoted, schema-qualified target table, TargetKey its
	// key column, and TargetName the unique column holding its resource name
	// ("" when the target is keyed by the last id of its name).
	TargetTable, TargetKey, TargetName string
	// Collection rebuilds a target's name from its key when Name is "":
	// Collection + "/" + key.
	Collection string
}

// quoteIdent double-quotes a column name.
func quoteIdent(s string) string { return `"` + strings.ReplaceAll(s, `"`, `""`) + `"` }

// dedupeNames drops repeats and empty names, keeping the first of each.
func dedupeNames(names []string) []string {
	out := make([]string, 0, len(names))
	seen := map[string]bool{}
	for _, n := range names {
		if n == "" || seen[n] {
			continue
		}
		seen[n] = true
		out = append(out, n)
	}
	return out
}

// TargetKeys returns the key of the target row each of names names. A name
// no row holds is an ErrForeignKey, as a foreign key refusing it would be.
func (j Join) TargetKeys(ctx context.Context, db *gorm.DB, names []string) (map[string]string, error) {
	keys := make(map[string]string, len(names))
	if j.TargetName == "" {
		for _, n := range names {
			if j.Collection != "" && !strings.HasPrefix(n, j.Collection+"/") {
				return nil, fmt.Errorf("%w: %s: %q is not a %s name", ErrInvalidArgument, j.Field, n, j.Collection)
			}
			keys[n] = LastSegment(n)
		}
		return keys, nil
	}
	var rows []struct{ K, N string }
	q := "SELECT " + quoteIdent(j.TargetKey) + " AS k, " + quoteIdent(j.TargetName) + " AS n FROM " + j.TargetTable +
		" WHERE " + quoteIdent(j.TargetName) + " IN ?"
	if err := db.WithContext(ctx).Raw(q, names).Scan(&rows).Error; err != nil {
		return nil, err
	}
	for _, r := range rows {
		keys[r.N] = r.K
	}
	for _, n := range names {
		if _, ok := keys[n]; !ok {
			return nil, fmt.Errorf("%w: %s: no record named %q", ErrForeignKey, j.Field, n)
		}
	}
	return keys, nil
}

// Write replaces owner's rows with one per name, in order; repeats keep
// their first place. Run it inside the owner's write transaction.
func (j Join) Write(ctx context.Context, tx *gorm.DB, owner string, names []string) error {
	db := tx.WithContext(ctx)
	if err := db.Exec("DELETE FROM "+j.Table+" WHERE "+quoteIdent(j.Owner)+" = ?", owner).Error; err != nil {
		return err
	}
	names = dedupeNames(names)
	if len(names) == 0 {
		return nil
	}
	keys, err := j.TargetKeys(ctx, tx, names)
	if err != nil {
		return err
	}
	cols := []string{quoteIdent(j.Key), quoteIdent(j.Owner), quoteIdent(j.Target)}
	tuple := "(?, ?, ?)"
	if j.Name != "" {
		cols = append(cols, quoteIdent(j.Name))
		tuple = "(?, ?, ?, ?)"
	}
	values := make([]string, 0, len(names))
	args := make([]any, 0, len(names)*len(cols))
	for _, n := range names {
		values = append(values, tuple)
		args = append(args, NewULID(), owner, keys[n])
		if j.Name != "" {
			args = append(args, n)
		}
	}
	return db.Exec("INSERT INTO "+j.Table+" ("+strings.Join(cols, ", ")+") VALUES "+strings.Join(values, ", "), args...).Error
}

// Read returns the names each of owners holds, in the order they were
// written.
func (j Join) Read(ctx context.Context, db *gorm.DB, owners []string) (map[string][]string, error) {
	out := map[string][]string{}
	if len(owners) == 0 {
		return out, nil
	}
	name := quoteIdent(j.Target)
	if j.Name != "" {
		name = quoteIdent(j.Name)
	}
	var rows []struct{ O, N string }
	q := "SELECT " + quoteIdent(j.Owner) + " AS o, " + name + " AS n FROM " + j.Table +
		" WHERE " + quoteIdent(j.Owner) + " IN ? ORDER BY " + quoteIdent(j.Key)
	if err := db.WithContext(ctx).Raw(q, owners).Scan(&rows).Error; err != nil {
		return nil, err
	}
	for _, r := range rows {
		n := r.N
		if j.Name == "" && j.Collection != "" {
			n = j.Collection + "/" + n
		}
		out[r.O] = append(out[r.O], n)
	}
	return out, nil
}

// FacetExpr is the SQL expression yielding a filter field's values, one row
// per value: a column (cast to text), each element of an array, the value of
// a value object the row points at, each element of a repeated reference kept
// in a join table, or a path under a JSON document.
func FacetExpr(spec filterx.Spec, field string) (string, error) {
	col := func(c string) string { return spec.Table + `."` + c + `"` }
	if f, ok := spec.Fields[field]; ok {
		switch {
		case f.Via != nil && f.Via.Many:
			return "unnest(ARRAY(SELECT " + f.Via.Table + `."` + f.Via.Column + `"::text FROM ` + f.Via.Table +
				" WHERE " + f.Via.Table + `."` + f.Via.Key + `" = ` + col(f.Column) + "))", nil
		case f.Via != nil:
			return "(SELECT " + f.Via.Table + `."` + f.Via.Column + `"::text FROM ` + f.Via.Table +
				" WHERE " + f.Via.Table + `."` + f.Via.Key + `" = ` + col(f.Column) + ")", nil
		case f.Kind == filterx.KindTags:
			return "unnest(" + col(f.Column) + ")::text", nil
		case f.Kind == filterx.KindJSON:
			return "", fmt.Errorf("%w: facet on a path under %q, not the document", ErrInvalidArgument, field)
		default:
			return col(f.Column) + "::text", nil
		}
	}
	path, ok, err := filterx.LookupJSON(spec, field)
	if err != nil {
		return "", MapFilterxErr(err)
	}
	if !ok {
		return "", fmt.Errorf("%w: cannot facet by %q", ErrInvalidArgument, field)
	}
	// LookupJSON admits only [A-Za-z0-9_-] segments, so the path is safe
	// inline.
	return col(path.Field.Column) + " #>> '{" + strings.Join(path.Path, ",") + "}'", nil
}

// FacetGorm counts the rows q selects (a scoped, filtered query over the
// resource's table) by the values of expr (FacetExpr), most frequent first,
// at most limit values (all when limit is not positive).
func FacetGorm(ctx context.Context, q *gorm.DB, expr string, limit int) ([]Bucket, error) {
	// The outer query is a new one, its context set in the same session: a
	// WithContext after it would copy q's conditions back in.
	sub := q.Session(&gorm.Session{}).Select(expr + " AS v")
	out := q.Session(&gorm.Session{NewDB: true, Context: ctx}).
		Table("(?) AS f", sub).
		Select("v AS value, count(*) AS count").
		Where("v IS NOT NULL").
		Group("v").
		Order("count DESC, value")
	if limit > 0 {
		out = out.Limit(limit)
	}
	var buckets []Bucket
	return buckets, MapGormErr(out.Scan(&buckets).Error)
}

// ReachesVia reports whether any of conds, or an alternative inside one,
// names a field reached through another table (filterx.Via): a condition the
// GraphQL engine matches page by page, which an aggregate cannot.
func ReachesVia(spec filterx.Spec, conds []filterx.Condition) bool {
	for _, c := range conds {
		if filterx.IsComposite(c) {
			if ReachesVia(spec, c.Any) {
				return true
			}
			continue
		}
		if f, ok := spec.Fields[c.Field]; ok && f.Via != nil {
			return true
		}
	}
	return false
}

// AnyHint reports whether any of conds is a hint (filterx.AsHint): a
// condition an engine may leave out and the caller filters by itself, which
// an aggregate therefore cannot count.
func AnyHint(conds []filterx.Condition) bool {
	for _, c := range conds {
		if c.Hint {
			return true
		}
	}
	return false
}

// FacetValues returns the facet values of field in a GraphQL row read into a
// map (RowMap), matching FacetExpr: a column's value, each element of an
// array, or a path under a JSON document. A field reached through another
// table yields nothing here; the caller supplies those values.
func FacetValues(spec filterx.Spec, field string, row map[string]any) []string {
	if f, ok := spec.Fields[field]; ok {
		if f.Via != nil {
			return nil
		}
		v := row[filterx.CamelCase(f.Column)]
		if v == nil {
			return nil
		}
		if items, ok := v.([]any); ok {
			out := make([]string, 0, len(items))
			for _, x := range items {
				out = append(out, fmt.Sprint(x))
			}
			return out
		}
		return []string{fmt.Sprint(v)}
	}
	path, ok, _ := filterx.LookupJSON(spec, field)
	if !ok {
		return nil
	}
	var doc any
	switch raw := row[filterx.CamelCase(path.Field.Column)].(type) {
	case nil:
		return nil
	case string:
		if json.Unmarshal([]byte(raw), &doc) != nil {
			return nil
		}
	default:
		doc = raw
	}
	for _, seg := range path.Path {
		m, ok := doc.(map[string]any)
		if !ok {
			return nil
		}
		doc = m[seg]
	}
	if doc == nil {
		return nil
	}
	if s, ok := doc.(string); ok {
		return []string{s}
	}
	b, _ := json.Marshal(doc)
	return []string{string(b)}
}

// SortBuckets orders counts most frequent first, then by value, keeping at
// most limit (all when limit is not positive).
func SortBuckets(counts map[string]int64, limit int) []Bucket {
	out := make([]Bucket, 0, len(counts))
	for v, n := range counts {
		out = append(out, Bucket{Value: v, Count: n})
	}
	slices.SortFunc(out, func(a, b Bucket) int {
		if a.Count != b.Count {
			if a.Count > b.Count {
				return -1
			}
			return 1
		}
		return strings.Compare(a.Value, b.Value)
	})
	if limit > 0 && len(out) > limit {
		out = out[:limit]
	}
	return out
}
